// DOMINION slice D26 (round-4 polish): the stage wears the Nova livery, key strips lead with the hold-Q wheel key, and
// dominion.css is the round-4 port (generated by tools/dominion/port-mockup-css.py from mockups-v4).
import { readdirSync, readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { stage, WHEEL_KEY } from '../../src/ui/redux/screens/dominion/views';

const css = readFileSync('src/ui/redux/screens/dominion/dominion.css', 'utf8');

describe('D26 Nova livery', () => {
  it('every stage ends with the sigil and the crimson underlight, both out of the way of taps', () => {
    const html = stage('<div class="pnl"></div>');
    expect(html).toContain('<div class="sig4" aria-hidden="true"></div><div class="vl4" aria-hidden="true"></div>');
    expect(html.indexOf('pnl')).toBeLessThan(html.indexOf('sig4'));
    expect(css).toMatch(/#rx \.dom \.vl4\{[^}]*pointer-events:none/);
    expect(css).toMatch(/#rx \.dom \.sig4\{[^}]*pointer-events:none/);
  });

  it('only stage() draws the livery layers, so no screen gets two sigils', () => {
    const dir = 'src/ui/redux/screens/dominion/';
    for (const f of readdirSync(dir).filter((n) => n.endsWith('.ts') && n !== 'views.ts')) {
      expect(readFileSync(dir + f, 'utf8'), f).not.toMatch(/class="(sig4|vl4)/);
    }
  });

  it('puts the sigil left or centre where the mockup does, and right by default', () => {
    expect(stage('', '', 'vign grain', 'c')).toContain('class="sig4 c"');
    expect(stage('', '', 'vign grain', 'l')).toContain('class="sig4 l"');
    expect(stage('')).not.toMatch(/sig4 [lc]/);
  });

  it('dominion.css is the round-4 port: Nova vars, the eye, lock-on, every v4 interval, keyframes prefixed', () => {
    expect(css.startsWith('/* Generated by tools/dominion/port-mockup-css.py')).toBe(true);
    expect(css).toContain('#rx .dom .st{--edge:#9a64d8;--edge2:#5e3a8e;--blood:#c2183a;--blood-l:#ff4d63}');
    for (const c of ['.q4', '.wheel', '.shut', '.blade', '.paper', '.onair', '.bigstamp']) expect(css).toContain(`#rx .dom ${c}`);
    expect(css).toContain('@keyframes dm-lock4');
    expect(css).not.toMatch(/@keyframes (?!dm-)/);
    // Motion stops for players who ask for it: every looping v4 animation sits under no-preference.
    expect(css).toMatch(/@media \(prefers-reduced-motion:no-preference\)\{[^]*dm-eye4/);
  });

  it('the wheel key is Q, and only Q (Quit moved to End, Crew File paging to the arrows)', () => {
    expect(WHEEL_KEY).toBe('<span class="key q4">Q</span><span>Wheel</span>');
  });
});
